package io.honeydelight.manager;

import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.content.res.Configuration;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.*;

/** Optional release notifier/downloader. Never requests root or reads learned models. */
public final class MainActivity extends Activity {
 final ExecutorService worker=Executors.newSingleThreadExecutor();
 TextView status,detail;Button check,download,open;Updates.Release latest;int ink,muted,card,base;boolean busy;
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView label(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(4),0,dp(8));return t;}
 GradientDrawable background(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 LinearLayout card(LinearLayout parent){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(20),dp(17),dp(20),dp(17));c.setBackground(background(card,24));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(14),0,0);parent.addView(c,p);return c;}
 Button button(LinearLayout parent,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(0xff302015);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffefbb60));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(10),0,0);parent.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle state){
  super.onCreate(state);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("updates","Actualizaciones de HoneyDelight",NotificationManager.IMPORTANCE_DEFAULT));boolean dark=(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;
  base=dark?0xff191713:0xfffff8ec;card=dark?0xff29251e:0xffffeed0;ink=dark?0xfffff2dc:0xff302015;muted=dark?0xffc9bda8:0xff6c5a40;
  getWindow().setStatusBarColor(base);getWindow().setNavigationBarColor(base);if(!dark)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(base);LinearLayout column=new LinearLayout(this);column.setOrientation(1);column.setPadding(dp(22),dp(24),dp(22),dp(32));scroll.addView(column);setContentView(scroll);
  try{ImageView banner=new ImageView(this);banner.setImageDrawable(android.graphics.drawable.Drawable.createFromStream(getAssets().open("banner.png"),null));banner.setAdjustViewBounds(true);column.addView(banner,new LinearLayout.LayoutParams(-1,-2));}catch(IOException e){column.addView(label("HoneyDelight",34,ink));}
  column.addView(label("El módulo primero. La app te mantiene al día.",20,ink));
  LinearLayout updates=card(column);status=label("Actualizaciones",23,ink);updates.addView(status);detail=label("Consulta las publicaciones de SuperProgramer64 y descarga el módulo compatible con tu compilación.",15,muted);updates.addView(detail);
  check=button(updates,"Buscar actualizaciones",this::check);download=button(updates,"Descargar módulo",this::download);download.setEnabled(false);
  open=button(updates,"Abrir módulo descargado",this::open);open.setEnabled(Updates.prefs(this).getString("uri",null)!=null);
  LinearLayout automatic=card(column);automatic.addView(label("Sin estar pendiente",22,ink));Switch toggle=new Switch(this);toggle.setText("Descargar automáticamente");toggle.setTextSize(16);toggle.setTextColor(ink);toggle.setChecked(Updates.prefs(this).getBoolean("automatic",true));automatic.addView(toggle,new LinearLayout.LayoutParams(-1,dp(52)));
  automatic.addView(label("Comprueba aproximadamente cada 6 horas en redes sin medición, como Wi-Fi. Te avisa cuando el ZIP está verificado en Descargas/HoneyDelight. Tú eliges cuándo instalarlo.",15,muted));
  toggle.setOnCheckedChangeListener((b,on)->{Updates.prefs(this).edit().putBoolean("automatic",on).apply();UpdateJob.schedule(this,on);if(on)askNotifications();});
  button(automatic,"Activar avisos",this::askNotifications);
  LinearLayout privacy=card(column);privacy.addView(label("Tus palabras se quedan contigo",22,ink));privacy.addView(label("Esta app no usa root ni lee historiales, contactos o modelos aprendidos. Internet se utiliza para consultar GitHub y descargar las publicaciones.",15,muted));
  LinearLayout install=card(column);install.addView(label("Instala el ZIP directamente",22,ink));install.addView(label("La app es opcional. Puedes descargar el módulo desde GitHub e instalarlo con KernelSU o Magisk, sin usar esta app. La activación y el primer arranque siguen en fase alpha.",15,muted));button(install,"Ver publicaciones en GitHub",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(Updates.PAGE))));
  column.addView(label("0.1.0-alpha.1 · SuperProgramer64",13,muted));UpdateJob.schedule(this,toggle.isChecked());
 }
 void askNotifications(){if(checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},1);else Toast.makeText(this,"Los avisos ya están activados",Toast.LENGTH_SHORT).show();}
 void lock(boolean value){busy=value;check.setEnabled(!value);download.setEnabled(!value&&latest!=null);open.setEnabled(!value&&Updates.prefs(this).getString("uri",null)!=null);}
 void check(){if(busy)return;lock(true);status.setText("Buscando actualizaciones…");detail.setText("Consultando las publicaciones oficiales en GitHub.");worker.execute(()->{Updates.Release release=null;String error=null;try{release=Updates.latest(this);}catch(Exception e){error=e.getMessage();}final Updates.Release found=release;final String issue=error;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;latest=found;lock(false);if(issue!=null){status.setText("No se pudo completar la consulta");detail.setText(issue);}else if(found==null){status.setText("Todavía no hay publicaciones");detail.setText("El repositorio aún no tiene módulos publicados para descargar. Cuando se publique la primera versión compatible aparecerá aquí.");}else{status.setText("Disponible: "+found.tag);detail.setText(found.name+"\nEl archivo coincide con tu compilación y se verificará antes de guardarlo.");}});});}
 void download(){if(busy||latest==null)return;final Updates.Release release=latest;lock(true);status.setText("Descargando "+release.tag+"…");detail.setText("Se comprobará el SHA-256 antes de guardar el ZIP.");worker.execute(()->{String error=null;try{Updates.download(this,release);}catch(Exception e){error=e.getMessage();}final String issue=error;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;lock(false);status.setText(issue==null?"Módulo verificado y guardado":"Descarga no completada");detail.setText(issue==null?"Está en Descargas/HoneyDelight. Ábrelo con tu gestor root cuando quieras instalarlo.":issue);});});}
 void open(){String value=Updates.prefs(this).getString("uri",null);if(value==null)return;try{Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(value),"application/zip").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Abrir módulo con…"));}catch(Exception e){Toast.makeText(this,"Abre Descargas/HoneyDelight desde tu gestor root",Toast.LENGTH_LONG).show();}}
 @Override protected void onDestroy(){super.onDestroy();worker.shutdown();}
}
